66	
67	  test('onOpen(trigger) captures the passed element as triggerRef.current — one real trigger origin', () => {
68	    let latest: ReturnType<typeof useCartDrawerState> | undefined;
69	    render(<StateProbe onState={(s) => (latest = s)} />);
70	    const headerBagIcon = document.createElement('button');
71	    headerBagIcon.setAttribute('data-origin', 'header-bag-icon');
72	
73	    act(() => latest?.onOpen(headerBagIcon));
74	
75	    expect(latest?.triggerRef.current).toBe(headerBagIcon);
76	  });
77	
78	  test('a second onOpen(trigger) from a different origin overwrites triggerRef.current — the second real trigger origin', () => {
79	    let latest: ReturnType<typeof useCartDrawerState> | undefined;
80	    render(<StateProbe onState={(s) => (latest = s)} />);
81	    const headerBagIcon = document.createElement('button');
82	    const pdpAddToBagButton = document.createElement('button');
83	    pdpAddToBagButton.setAttribute('data-origin', 'pdp-add-to-bag');
84	
85	    act(() => latest?.onOpen(headerBagIcon));
86	    expect(latest?.triggerRef.current).toBe(headerBagIcon);
