169	 */
170	export const CartDrawerContainer = ({ isOpen, onClose, finalFocusRef }: CartDrawerContainerProps) => {
171	  const { data: basket } = useCurrentBasket() as unknown as UseCurrentBasketReturn;
172	  const productItems: SfccBasketProductItem[] = basket?.productItems ?? [];
