286	    if (!isRegistered) {
287	      setIsGuestState(true);
288	      return;
289	    }
290	    // Steady-state (a shopper already registered when this container mounts) never sets the ref,
291	    // so `!hasPendingPostAuthSettleRef.current` is true immediately — no artificial wait for
