294	      hasPendingPostAuthSettleRef.current = false;
295	      setIsGuestState(false);
296	    }
297	  }, [isRegistered, isMutatingSignal, queryClient]);
298	
299	  /**
300	   * Opens the one shared wishlist auth drawer from any row's guest click. ZimmCartItemActions'
301	   * onGuestWishlistClick is `() => void` — no event to forward, because every row shares this one
302	   * drawer instance (ZimmCartItemActions' own docblock explicitly rejects one useWishlistAuthDrawer
303	   * per row). useWishlistAuthDrawer's handleTriggerClick needs a SyntheticEvent purely to capture
304	   * `e.currentTarget` as the AC10 focus-return target.
305	   *
306	   * document.activeElement is deliberately NOT used as a substitute here, even though it could
307	   * plausibly hold the real clicked row's own link at this exact point in the call stack:
308	   * useWishlistAuthDrawer.ts's own handleTriggerClick comment already documents exactly why it
309	   * chose `e.currentTarget` over `document.activeElement` for this identical purpose — "unlike
310	   * document.activeElement which may still be body on click." Building this on a mechanism that
311	   * file's own author already rejected for the same job would trade one honest degradation for a
312	   * silently unreliable one.
313	   *
314	   * Corrected 2026-09-21 (step 4.6's own Tester, live-rendered rather than assumed): an earlier
315	   * version of this comment claimed the fallback lands on `document.body`, citing ZimmCartDrawer's
316	   * own doc for that behaviour. That doc describes what Chakra does with no `finalFocusRef` at
317	   * all — not what actually happens here, where `document.body` IS passed as `currentTarget`.
318	   * Live-rendering the real close sequence instead, focus actually lands on the still-open outer
319	   * cart drawer's own `aria-hidden` initial-focus sentinel (ZimmDrawer's own focus-management
320	   * internals) — a real, disclosed, named degradation, just a different actual mechanism than
321	   * previously claimed here: a keyboard user ends up parked on an invisible, unannounced element
322	   * rather than on `document.body`. Worth a follow-up ticket on the real UX gap; not fixed in this
323	   * step, which only owns getting this comment's own factual claim right. AC10 remains fully
324	   * correct for every genuine single-trigger caller (header/PDP wishlist icon), which still goes
325	   * through the unmodified <ZimmWishlistAuthDrawer/> wrapper, not this container.
326	   */
327	  const openGuestWishlistDrawer = useCallback(() => {
328	    wishlistAuthDrawer.handleTriggerClick({ currentTarget: document.body } as unknown as SyntheticEvent<HTMLElement>);
329	  }, [wishlistAuthDrawer.handleTriggerClick]);
330	
331	  /* -------------------------------------------------------------------------------------------
332	   * Pass criterion 3 — real remove/wishlist-move mutations, not stubs.
333	   * ---------------------------------------------------------------------------------------- */
334	  const removeItemFromBasketMutation = useShopperBasketsMutation('removeItemFromBasket');
335	  const customerId = useCustomerId();
336	  const { data: wishlist } = useWishList();
337	  const createCustomerProductListItem = useShopperCustomersMutation('createCustomerProductListItem');
338	
339	  const removeItem = async (itemId?: string): Promise<void> => {
340	    if (!basket?.basketId || !itemId) return;
341	    await removeItemFromBasketMutation.mutateAsync({ parameters: { basketId: basket.basketId, itemId } });
342	  };
343	
344	  const moveToWishlist = async (productId: string): Promise<WishlistMoveResult> => {
345	    // Same lookup base product-detail/index.tsx's own handleAddToWishlist uses against
346	    // wishlist?.customerProductListItems.
347	    const isAlreadyInWishlist = wishlist?.customerProductListItems?.some(
348	      (item: { productId?: string }) => item.productId === productId,
349	    );
350	    if (isAlreadyInWishlist) {
351	      return { status: 'already-in-wishlist' };
352	    }
353	    if (!wishlist?.id) {
354	      // useWishList() auto-provisions a wish_list for a first-time registered customer and only
355	      // resolves it asynchronously (see that hook's own onSuccess) — surfaced as an error rather
356	      // than silently doing nothing, matching useCartMergeAndCap.ts's own "nothing valid to
357	      // address a write at" precedent.
358	      return { status: 'error', error: new Error('cartDrawerContainer: no wishlist available yet.') };
359	    }
360	    try {
361	      await createCustomerProductListItem.mutateAsync({
362	        parameters: {
363	          listId: wishlist.id,
364	          // SDK param widening — useCustomerId returns string | null; onMoveToWishlist is only
365	          // ever invoked for a registered shopper (ZimmCartItemActions only calls this prop
366	          // directly when isGuest is false, and the resumed path only fires once isGuest has
367	          // become false — see usePendingWishlistItem.ts), matching product-detail/index.tsx's
368	          // own identical cast for the same real precondition.
369	          customerId: customerId as string,
370	        },
371	        body: {
372	          // NOTE: API does not respect quantity, it always adds 1 — see WISHLIST_ADD_QUANTITY's
373	          // own comment above.
374	          quantity: WISHLIST_ADD_QUANTITY,
375	          productId,
376	          public: false,
377	          priority: 1,
378	          type: 'product',
379	        },
380	      });
381	      return { status: 'success' };
382	    } catch (error) {
383	      return { status: 'error', error };
384	    }
385	  };
386	
387	  return (
388	    <>
389	      <ZimmCartDrawer
390	        isOpen={isOpen}
391	        onClose={onClose}
392	        itemCount={itemCount}
393	        finalFocusRef={finalFocusRef}
394	        footer={<ZimmCartButtonGroup />}
395	      >
396	        {itemCount === 0 ? (
397	          <ZimmCartEmptyState />
398	        ) : (
399	          productItems.map((item) => {
400	            const fullProduct = item.productId ? productsById?.[item.productId] : undefined;
401	            const mergedProduct = {
402	              ...item,
403	              ...fullProduct,
404	              // Re-asserted after both spreads, matching base's own precedent exactly: the fetched
405	              // catalog Product record can carry its own `price` field, which would otherwise
406	              // silently overwrite the basket-line's real, discount-aware price.
407	              price: item.price,
408	              quantity: item.quantity,
409	              isProductUnavailable: !isProductsLoading ? !fullProduct : undefined,
410	            };
411	            // Pass criterion 1 — cartItemMapper's output used verbatim: productId/name feed
412	            // ZimmCartItemActions below (as productId/productName) — not a second, hand-rolled
413	            // mapping. The full mergedProduct object, not this mapped result, is what ProductItem
414	            // itself needs (see this file's own module docblock and cartItemMapper.ts's own
415	            // docblock for why its output alone is not a complete `product` prop).
416	            const mapped = selectCartItemProps(mergedProduct);
417	            return (
418	              <ProductItem
419	                key={item.itemId}
420	                product={mergedProduct}
421	                secondaryActions={
422	                  <ZimmCartItemActions
423	                    productId={mapped.productId ?? ''}
424	                    productName={mapped.name}
425	                    isGuest={isGuestState}
426	                    onRemove={() => removeItem(item.itemId)}
427	                    onMoveToWishlist={() => moveToWishlist(mapped.productId ?? '')}
428	                    onGuestWishlistClick={openGuestWishlistDrawer}
429	                  />
430	                }
431	              />
432	            );
433	          })
434	        )}
435	      </ZimmCartDrawer>
436	      <CartWishlistAuthGate wishlistAuthDrawer={wishlistAuthDrawer} />
437	    </>
438	  );
439	};
